CREATE OR REPLACE FUNCTION refresh_events_hourly_metrics()
RETURNS void AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY events_hourly_metrics;
END;
$$ LANGUAGE plpgsql;

